import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Подарки и двусторонние сделки","description":"","frontmatter":{"pageId":"players/gifts-trades","contentRevision":1},"headers":[],"relativePath":"ru/players/gifts-trades.md","filePath":"ru/players/gifts-trades.md"}'),i={name:"ru/players/gifts-trades.md"};function l(o,a,n,d,p,h){return t(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="подарки-и-двусторонние-сделки" tabindex="-1">Подарки и двусторонние сделки <a class="header-anchor" href="#подарки-и-двусторонние-сделки" aria-label="Permalink to &quot;Подарки и двусторонние сделки&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p><strong>Подарок:</strong> выбери игрока и содержимое передачи. Получатель принимает, отказывается или откладывает решение; отказ возвращает эскроу отправителю. По умолчанию неотвеченный подарок отклоняется через 7 дней. Флаг приёма подарков и блокировка влияют на новые предложения.</p><p><strong>Сделка:</strong> открой предложение, добавь вещи, пешек, серебро и заметку. Вторая сторона меняет свою часть. Любое изменение делает прежние подтверждения недействительными: обе стороны должны подтвердить одну и ту же ревизию. Отмена/истечение возвращает вклад владельцам. Проверь итоговый состав перед подтверждением.</p><p>После обрыва сначала обнови состояние сделки. Не отправляй те же вещи новым подарком, пока исход первой операции неизвестен.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>По умолчанию сделка живёт 7 дней, открытых сделок максимум 5. Закрытые сделки и запрет подарков — разные настройки. Никто не должен сообщать пароль для принятия передачи.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./economy">Кошелёк, почта и рынок</a></li><li><a href="./chat-pings">Чат, сообщения и пинги</a></li><li><a href="./saves-recovery">Сохранения и восстановление</a></li></ul>',10)])])}const _=e(i,[["render",l]]);export{u as __pageData,_ as default};
